'use client'
import {useEffect,useRef,useState} from 'react'
import {Check,Loader2} from 'lucide-react'
import {getPlatformLogo,getPlatformMeta} from '@/vendor/mm-video/components/dashboard/../shared/platformUtils'
import type {VideoProductionJob} from '@/vendor/mm-video/components/dashboard/../shared/types'
import {VIDEO_LANGUAGES,isScriptLanguage,platformVideoLanguage,type ScriptLanguage} from '@/vendor/mm-video/lib/video-languages'
import {videoButton,videoPrimary,type VideoTranslate} from '@/vendor/mm-video/components/dashboard/VideoWorkspaceShell'
export default function VideoChannelVersions({job,t,onOpenVersion,onPlatformsChange,onReadyChange}:{job:VideoProductionJob;t:VideoTranslate;onOpenVersion?:(job:VideoProductionJob)=>void;onPlatformsChange?:(platforms:string[])=>unknown;onReadyChange?:(ready:boolean)=>void}){
 const [context,setContext]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[confirm,setConfirm]=useState<string|null>(null),[language,setLanguage]=useState<ScriptLanguage>('en'),[selected,setSelected]=useState<string[]>([]),[retry,setRetry]=useState(0)
 const lock=useRef(false),alive=useRef(true),attempted=useRef(new Set<string>())
 const [progress,setProgress]=useState(''),[convert,setConvert]=useState(false),[unresolved,setUnresolved]=useState<{platform:string;language:ScriptLanguage}|null>(null)
 const versionReady=(v:any)=>Boolean(v.finalVideoUrl)||['READY','COMPLETED','completed','ready'].includes(v.status)
 const allVersions=[...(context?.rootVersion?[context.rootVersion]:[]),...(context?.versions||[])].filter((v:any,i:number,a:any[])=>a.findIndex(x=>x.jobId&&x.jobId===v.jobId||x.key&&x.key===v.key)===i)
 const currentLanguage=job.language||job.editor?.language
 const requested=job.editor?.generationLanguages||[]
 useEffect(()=>{setUnresolved(null);setProgress('');setError('')},[job.id])
 useEffect(()=>{alive.current=true;const controller=new AbortController();setContext(null);onReadyChange?.(false);void fetch(`/api/brands/${encodeURIComponent(job.brandId)}/video-preparation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'variants',jobId:job.id}),signal:controller.signal}).then(async r=>{const data=await r.json();if(!r.ok)throw Error();return data}).then(data=>{if(alive.current&&!controller.signal.aborted){setContext(data);const defaults=[job.platform||'tiktok'];const next=Array.isArray(job.editor?.targetPlatforms)?job.editor.targetPlatforms.filter(p=>['xiaohongshu','tiktok'].includes(p)):defaults;setSelected(next);onReadyChange?.(next.length>0)}}).catch(()=>{if(!controller.signal.aborted)setError(t('渠道版本暂不可用，请重试。','Channel versions unavailable. Retry.'))});return()=>{alive.current=false;controller.abort()}},[job.id,job.brandId,retry])
 const open=async(id:string)=>{const r=await fetch(`/api/video-editor/jobs?id=${encodeURIComponent(id)}`,{cache:'no-store'});const data=await r.json();if(!r.ok||!data.job||data.job.brandId!==job.brandId||data.job.ownedByCurrentActor!==true)throw Error();if(alive.current)onOpenVersion?.(data.job)}
 const checkPending=async(platform:string,target:ScriptLanguage,existingId?:string)=>{
  if(lock.current)return;lock.current=true;setBusy(true);setError('')
  try{const r=await (existingId?fetch(`/api/video-editor/jobs?id=${encodeURIComponent(existingId)}`,{cache:'no-store'}):fetch('/api/video-editor/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'variant',id:context?.rootId||job.id,platform,language:target})}));const data=await r.json();if(!r.ok||!data.job){setError(data.error||t('此版本尚在处理中，请稍后核对。','This version is still processing. Check again shortly.'));return}if(alive.current&&data.job.brandId===job.brandId&&data.job.ownedByCurrentActor===true){setUnresolved(null);setProgress(data.job.finalVideoUrl?t('版本已准备，可点击打开。','Version is ready. Select it to open.'):t('版本仍在制作，请稍后核对。','Version is still being made. Check again shortly.'));setRetry(n=>n+1)}}catch{if(alive.current)setError(t('暂未取得进度，请稍后核对。','Progress is unavailable. Check again shortly.'))}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 useEffect(()=>{
  if(!context||busy||unresolved||!requested.length)return
  const pending=allVersions.find((v:any)=>v.jobId&&v.jobId!==job.id&&requested.includes(v.language)&&!versionReady(v)&&!/fail|cancel/i.test(v.status||''))
  if(!pending)return
  const controller=new AbortController(),timer=setTimeout(()=>{
   void fetch(`/api/video-editor/jobs?id=${encodeURIComponent(pending.jobId)}`,{cache:'no-store',signal:controller.signal}).then(async r=>{const data=await r.json();if(!r.ok||!data.job||data.job.brandId!==job.brandId||data.job.ownedByCurrentActor!==true)throw Error(data.error||'Progress unavailable');if(alive.current&&!controller.signal.aborted)setRetry(n=>n+1)}).catch(()=>{if(!controller.signal.aborted){setUnresolved({platform:pending.platform,language:pending.language});setError(t('暂未取得语言版本进度，请点击核对。','Language version progress unavailable. Select Check progress.'))}})
  },4000)
  return()=>{clearTimeout(timer);controller.abort()}
 },[context,busy,unresolved,job.id,JSON.stringify(requested)])
 const choose=async(platform:string)=>{
  if(busy||!context||!onOpenVersion)return
  if(selected.includes(platform)){const next=selected.filter(p=>p!==platform);setBusy(true);try{if(await onPlatformsChange?.(next)===false)throw Error();setSelected(next);onReadyChange?.(next.length>0)}catch{setError(t('渠道选择未保存，请重试。','Channel selection was not saved. Retry.'))}finally{setBusy(false)}return}
  if(job.platform===platform){const next=[...selected,platform];setBusy(true);try{if(await onPlatformsChange?.(next)===false)throw Error();setSelected(next);onReadyChange?.(next.length>0)}catch{setError(t('渠道选择未保存，请重试。','Channel selection was not saved. Retry.'))}finally{setBusy(false)}return}
  const target=platformVideoLanguage(platform,context.market),existing=[...(context.versions||[]),...(context.rootVersion?[context.rootVersion]:[])].find((v:any)=>v.platform===platform&&(!target||v.language===target)&&v.jobId)
  if(existing){setBusy(true);try{await open(existing.jobId)}catch{setError(t('无法打开此版本，请重试。','Could not open this version. Retry.'))}finally{setBusy(false)};return}
  const pending=context.versions?.find((v:any)=>v.platform===platform&&(!target||v.language===target)&&!v.jobId);if(pending){await checkPending(platform,pending.language);return}

  if(target)setLanguage(target);setConfirm(platform)
 }
 const generate=async()=>{
  if(lock.current||!confirm)return;const found=allVersions.find((v:any)=>v.platform===confirm&&v.language===language);if(found){setConfirm(null);setConvert(false);if(found.jobId){setBusy(true);try{await open(found.jobId)}catch{setError(t('无法打开此版本。','Could not open this version.'))}finally{setBusy(false)}}else await checkPending(confirm,language);return}lock.current=true;setBusy(true);setError('');const platform=confirm;setConfirm(null);setConvert(false)
  try{const r=await fetch('/api/video-editor/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'variant',id:job.id,platform,language})});const data=await r.json();if(!r.ok){if(data.pending){setError(data.error||t('此版本正在处理中，请稍后点击核对，不会重复制作。','This version is processing. Check again shortly; it will not be created twice.'));setRetry(n=>n+1);return}throw Error(data.error)}if(!data.job||data.job.brandId!==job.brandId||data.job.ownedByCurrentActor!==true)throw Error();if(alive.current)onOpenVersion?.(data.job)}catch(e){if(alive.current){setUnresolved({platform,language});setError((e as Error).message||t('暂未取得版本结果，请再次点击核对原任务。','Version result unavailable. Click again to check the same request.'));setRetry(n=>n+1)}}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 useEffect(()=>{
  if(!context||busy||lock.current||!requested.length||!job.finalVideoUrl||unresolved)return
  if(allVersions.some((v:any)=>v.language!==currentLanguage&&requested.includes(v.language)&&!versionReady(v)))return
  const target=requested.find((lang:ScriptLanguage)=>lang!==currentLanguage&&!allVersions.some((v:any)=>v.language===lang)&&!attempted.current.has(`${context.rootId||job.id}:${lang}`))
  if(!target)return
  const key=`${context.rootId||job.id}:${target}`;attempted.current.add(key);lock.current=true;setBusy(true);setProgress(t(`正在准备 ${VIDEO_LANGUAGES[target as ScriptLanguage]} 版本…`,`Preparing ${VIDEO_LANGUAGES[target as ScriptLanguage]} version…`))
  void fetch('/api/video-editor/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'variant',id:context.rootId||job.id,platform:job.platform||'tiktok',language:target})}).then(async r=>{const data=await r.json();if(!r.ok||!data.job){setUnresolved({platform:job.platform||'tiktok',language:target});setError(data.error||t('版本仍在处理或结果未确认，请点击核对进度。','Version is processing or unconfirmed. Select Check progress.'));return}setProgress(data.job.finalVideoUrl?t('语言版本已准备，可点击打开。','Language version is ready. Select it to open.'):t('语言版本正在制作，请稍后核对进度。','Language version is being made. Check progress shortly.'))}).catch(()=>{setUnresolved({platform:job.platform||'tiktok',language:target});setError(t('暂未取得语言版本结果，请核对原任务。','Language version result unavailable. Check the same request.'))}).finally(()=>{lock.current=false;if(alive.current){setBusy(false);setRetry(n=>n+1)}})
 },[context,busy,job.id,job.finalVideoUrl,JSON.stringify(requested),unresolved])
 return <div className="border-y border-slate-100 bg-white px-4 py-3 sm:px-6"><div className="flex flex-wrap items-center gap-4"><span className="text-xs font-semibold text-slate-500">{t('发布渠道与语言','Channels & languages')}</span><div role="group" aria-label={t('渠道版本','Channel versions')} className="flex flex-wrap gap-3">{['xiaohongshu','tiktok'].map(platform=>{const meta=getPlatformMeta(platform,t('zh','en')==='en'),target=platform===job.platform&&isScriptLanguage(currentLanguage)?currentLanguage:platformVideoLanguage(platform,context?.market);return <button key={platform} aria-label={`${meta.label}${target?` · ${VIDEO_LANGUAGES[target]}`:''}`} aria-pressed={selected.includes(platform)} disabled={busy||!context||!onOpenVersion} onClick={()=>void choose(platform)} className={`relative flex min-h-12 items-center gap-2 rounded-xl border px-3 text-xs disabled:opacity-50 ${selected.includes(platform)?'border-teal-400 bg-teal-50':'border-slate-200 bg-white'}`}>{getPlatformLogo(platform,'h-7 w-7')}<span>{target?VIDEO_LANGUAGES[target]:t('选择市场语言','Choose market language')}</span>{selected.includes(platform)&&<Check size={14} className="text-teal-700"/>}</button>})}</div><button className={videoButton} disabled={busy||!context} onClick={()=>{setConvert(true);setLanguage(isScriptLanguage(currentLanguage)?currentLanguage:'zh');setConfirm(job.platform||'tiktok')}}>{t('转换语言','Convert language')}</button>{busy&&<Loader2 aria-label={t('正在准备版本','Preparing version')} size={18} className="animate-spin motion-reduce:animate-none text-teal-700"/>}</div>{allVersions.length>0&&<div className="mt-2 flex flex-wrap gap-2">{allVersions.filter((v:any)=>v.jobId&&(v.jobId===job.id||versionReady(v)||!v.status)).map((v:any)=><button key={v.key||v.jobId} className="min-h-9 rounded-lg bg-slate-50 px-3 text-xs text-teal-700" disabled={busy} onClick={()=>{setBusy(true);void open(v.jobId).catch(()=>setError(t('无法打开版本。','Could not open version.'))).finally(()=>setBusy(false))}}>{getPlatformMeta(v.platform,t('zh','en')==='en').label} · {VIDEO_LANGUAGES[v.language as ScriptLanguage]||v.language}</button>)}{allVersions.filter((v:any)=>!v.jobId||v.jobId!==job.id&&v.status&&!versionReady(v)).map((v:any)=><button key={v.key||v.jobId} className="min-h-9 rounded-lg bg-amber-50 px-3 text-xs text-amber-900" disabled={busy} onClick={()=>void checkPending(v.platform,v.language,v.jobId)}>{getPlatformMeta(v.platform,t('zh','en')==='en').label} · {VIDEO_LANGUAGES[v.language as ScriptLanguage]||v.language} · {/fail/i.test(v.status||'')?t('失败，核对进度','Failed · Check progress'):t('处理中，核对进度','Processing · Check progress')}</button>)}{context.rootId!==job.id&&<button className="min-h-9 px-3 text-xs text-teal-700 underline" disabled={busy} onClick={()=>void open(context.rootId).catch(()=>setError(t('无法打开初始版本。','Could not open initial version.')))}>{t('查看初始版本','View initial version')}</button>}</div>}{unresolved&&!allVersions.some((v:any)=>v.platform===unresolved.platform&&v.language===unresolved.language)&&<button className="mt-2 min-h-11 rounded-lg bg-amber-50 px-3 text-xs text-amber-900" disabled={busy} onClick={()=>void checkPending(unresolved.platform,unresolved.language)}>{VIDEO_LANGUAGES[unresolved.language]} · {t('结果未确认，核对进度','Unconfirmed · Check progress')}</button>}{requested.length>1&&<p className="mt-2 text-xs leading-6 text-slate-500">{t('所选语言已保存。保持此成片页面打开，依次准备各语言版本；重新打开后可继续核对。','Your selected languages are saved. Keep this final video page open to prepare versions in sequence. Reopen it to continue checking progress.')}</p>}{progress&&<p role="status" className="mt-2 text-xs text-teal-700">{progress}</p>}{error&&<p role="alert" className="mt-2 text-xs text-amber-800">{error} <button className="min-h-8 underline" onClick={()=>setRetry(n=>n+1)}>{t('刷新版本','Refresh versions')}</button></p>}
 {confirm&&<div className="fixed inset-0 z-[120] flex items-end justify-center bg-black/40 p-4 sm:items-center"><div role="dialog" aria-modal="true" aria-label={t('添加渠道版本','Add channel version')} className="max-h-[85dvh] w-full max-w-md overflow-y-auto rounded-2xl bg-white p-5"><h2 className="font-semibold">{convert?t('转换语言','Convert language'):t('添加渠道版本','Add channel version')} · {getPlatformMeta(confirm,t('zh','en')==='en').label}</h2><label className="mt-4 block text-sm">{t('视频语言','Video language')}<select className="mt-2 min-h-11 w-full rounded-xl border px-3" aria-label={t('渠道版本语言','Channel version language')} value={language} onChange={e=>setLanguage(e.target.value as ScriptLanguage)}>{Object.entries(VIDEO_LANGUAGES).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><p className="mt-4 text-sm leading-7 text-slate-500">{t('保留原成片的画面与时间轴，仅转换配音和字幕语言。此版本消耗 AMC Credit，完成后请检查并确认发布。','Keeps the completed visuals and timeline and converts voice and captions. This version uses AMC Credit. Review it before publishing.')}</p><div className="mt-5 flex justify-end gap-2"><button className={videoButton} onClick={()=>setConfirm(null)}>{t('取消','Cancel')}</button><button className={videoPrimary} onClick={()=>void generate()}>{t('确认制作此版本','Create this version')}</button></div></div></div>}
 </div>
}
